  for(const man of c.checks){const metric:Metric={inputHashAlgorithm:INPUT_HASH_ALGORITHM,check:man.id,hash:hash(Object.fromEntries(Object.entries(c.files).filter(([p])=>p.startsWith(`checks/${man.id}/`)))),tp:0,fp:0,fn:0,precision:null,recall:null,errors:0,agreement:man.kind==='judged'?{matched:0,total:0,ratio:null,vendors:[]}:null,misses:[],results:[]};
   for(const s of g.samples){if(x.cancelled())throw new Error('cancelled');this.assertSample(s);const out=await this.execute(x,man,s,c.root,c.hash);const predicted=man.kind==='judged'?out.findings.filter((f,i,all)=>!all.slice(0,i).some(old=>old.class===f.class&&sameLocator(old.locator,f.locator))):out.findings;const scored=scoreFindings(s.findings,predicted);
    metric.tp+=scored.tp;metric.fp+=scored.fp;metric.fn+=scored.fn;
    metric.misses.push(...scored.missed.map(f=>({sample:s.id,kind:'miss' as const,finding:f})),...scored.falseHits.map(f=>({sample:s.id,kind:'false-hit' as const,finding:f})));
    if(out.verdict==='error'){metric.errors++;metric.misses.push({sample:s.id,kind:'error',finding:null,error:out.error??'check error'});}
    metric.results.push({sample:s.id,verdict:out.verdict,seq:out.seq,inputHash:out.inputHash,votes:out.votes??[]});
    addAgreement(metric,out.votes??[]);
   }
   metric.precision=metric.tp+metric.fp?metric.tp/(metric.tp+metric.fp):null;metric.recall=metric.tp+metric.fn?metric.tp/(metric.tp+metric.fn):null;if(metric.agreement)metric.agreement.ratio=metric.agreement.total?metric.agreement.matched/metric.agreement.total:null;metrics.push(metric);
  }
