  const tmp=dest+'.publishing';mkdirSync(tmp,{recursive:true});cpSync(c.root,join(tmp,'files'),{recursive:true,errorOnExist:true,force:false});if(stable(packFiles(join(tmp,'files')))!==stable(c.files))throw new Error('publication copy changed');writeFileSync(join(tmp,'files','eval-set.json'),evalFile);const files=packFiles(join(tmp,'files'));const promoted=Object.entries(g.promotion).filter(([,p])=>p.blocking).map(([id])=>id);const unsigned={namespace,id:g.id,genesis:g.run,version,candidateHash:c.hash,evalHash:g.evalHash,files,promoted,kind:'published'};const pin={...unsigned,hash:hash(unsigned),sig:this.sign(unsigned)};
  if(x.cancelled())throw new Error('cancelled');mkdirSync(resolve(dest,'..'),{recursive:true});renameSync(tmp,dest);atomic(join(this.root,`pin-${namespace}.json`),pin);this.loadPin(this.pin(namespace,pin.hash));for(const flow of c.flows)this.engine.defs.importPinned(this.pinnedFlow(this.pin(namespace),flow,false),{hash:pin.hash,verify:()=>this.verifyPin(namespace,pin.hash)});
  g.published={version,hash:pin.hash,namespace};this.save(g);this.engine.record(x,'pack-published',{actor:'captain',head:pin.hash,data:{pack:g.id,version,evalHash:g.evalHash,metrics:hash(metrics),promoted}});return g.published;
