 engine.natives['pack-genesis-measure']=async(_i,h)=>{const x=h.x as X;const metrics=await pg.measure(x);return {verdict:metrics.some(m=>m.errors)?'warn':'pass',score:metrics.every(m=>!m.errors)?1:0,findings:[],data:{route:'review',metrics,evalHash:pg.get(x.run.id).evalHash}};};
 const guard=(x:X)=>{if(x.cancelled())throw new Error('cancelled');};
 engine.modes['pack-interview']={maxTools:2,sandbox:x=>({writes:[],cwd:pg.work(x.run.id)}),system:(x,s)=>s,prompt:x=>`NATIVE PACK INTERVIEW\nDescription: ${x.run.text}`,tools:x=>[tool('interview_batch','Write all six interview questions in one batch (key/en/zh).',a=>{guard(x);const keys=['inputs','outputs','tools','quality','dealbreakers','signoff'];if(!Array.isArray(a.questions)||a.questions.length!==keys.length||keys.some(k=>!a.questions.some((q:any)=>q.key===k&&q.en?.trim()&&q.zh?.trim())))throw new Error('provide every interview question in one batch, in both languages');const g=pg.get(x.run.id);g.questions=a.questions.map((q:any)=>({key:q.key,en:String(q.en).slice(0,300),zh:String(q.zh).slice(0,300)}));pg.save(g);return {ok:true};})],after:x=>{const g=pg.get(x.run.id);if(g.questions.length!==6)throw new Error('the interview batch was not written');engine.record(x,'pack-interview-batch',{data:{schema:1,hash:questionHash(g),origin:'native-round'}});return 'ok';}};
 engine.cardBodies['pack-interview']=x=>{const g=pg.get(x.run.id);return body('Answer the pack interview','回答套件訪談',g.questions.map(q=>`${q.key}: ${q.en}`).join('\n'),g.questions.map(q=>`${q.key}：${q.zh}`).join('\n'),[{id:'continue',label:'Save all answers',primary:true,note:true},{id:'close',label:'Close',hold:true}],[{label:'Interview answers',href:`#/pack-genesis/${x.run.id}`}]);};
 engine.modes['pack-samples']={maxTools:12,sandbox:x=>({writes:[pg.work(x.run.id)],cwd:pg.work(x.run.id)}),system:(_x,s)=>s,prompt:x=>`NATIVE PACK SAMPLES\nDescription: ${x.run.text}\nInterview: ${x.ctx.answers?.['interview-answers']?.note??''}`,tools:x=>[
  tool('sample_create','Create a local self-contained HTML sample artifact; never read arbitrary paths.',a=>{guard(x);const g=pg.get(x.run.id),index=g.samples.length+1,id=`genesis-${x.run.id.toLowerCase()}-${index}`,html=String(a.html??'');if(!html.includes('<')||html.length>300000||redactText(html)!==html)throw new Error('sample HTML is missing, too large or contains credentials');const dir=join(pg.work(x.run.id),'sample-inputs',String(index));mkdirSync(dir,{recursive:true});writeFileSync(join(dir,'index.html'),html);o.artifacts.create({id,title:String(a.title??id),type:'web',source:'html',entry:'index.html',project:'native-pack'});const v=o.artifacts.addVersion(id,{from:dir,primary:'index.html',createdBy:{kind:'agent',run:x.run.id},status:'in-review',source:{run:x.run.id}});return pg.sample(x.run.id,id,v.n);}),
  tool('sample_reference','Collect an existing intact local artifact version for captain labelling.',a=>{guard(x);return pg.sample(x.run.id,String(a.artifact),Number(a.version));})],after:x=>{if(pg.get(x.run.id).samples.length<2)throw new Error('collect at least two actual samples');return 'ok';}};
 engine.cardModes['pack-label']={async start(x){const g=pg.get(x.run.id);await engine.card(x,'question',body('Label the actual sample versions','標記實際樣本版本','Review each artifact using M3 pins or ranges. Mark at least one good and one bad sample. A bad sample needs an actual annotation.','使用 M3 定位或時間區段查看每個成品。至少標記一個好樣本和一個壞樣本。壞樣本需要實際標註。',[{id:'continue',label:'Use these labels',primary:true},{id:'close',label:'Close',hold:true}],[{label:'Label samples',href:`#/pack-genesis/${x.run.id}`},...g.samples.map(s=>({label:s.id,href:`#/review/${s.artifact}/${s.version}`}))]));return {wait:true};},async answer(x,c){if(c.answer!.choice==='continue')pg.evalSet(pg.get(x.run.id));return {outcome:c.answer!.choice};}};
 const authorMode=(refine:boolean)=>({maxTools:60,sandbox:(x:X)=>({writes:[pg.work(x.run.id)],cwd:pg.work(x.run.id)}),system:(_x:X,s:string)=>s,prompt:(x:X)=>{const g=pg.get(x.run.id);return `NATIVE PACK ${refine?'REFINE':'AUTHOR'}\nPack id: ${g.id}\nDescription: ${g.description}\nCandidate folder: pack-relative paths only\nInterview: ${x.ctx.answers?.['interview-answers']?.note??''}\nSamples and labels: ${stable(g.samples)}\nMeasurements: ${stable(g.metrics)}\nAccepted/edited proposals: ${stable(g.proposals.filter(p=>p.status==='accepted'||p.status==='edited'))}`;},tools:(x:X)=>folderTools(pg.work(x.run.id),()=>{guard(x);},'pack').filter(t=>!t.name.endsWith('_search')).map(t=>({...t,run:(a:any)=>{guard(x);if(t.name.endsWith('_write')&&(!safeRel(String(a.path))||redactText(String(a.content))!==String(a.content)))throw new Error('unsafe pack content');if(t.name.endsWith('_write')&&/^checks\/[a-z][a-z0-9-]+\/run$/.test(String(a.path))){const p=insideDir(pg.work(x.run.id),a.path,false);if(existsSync(p)&&(!lstatSync(p).isFile()||lstatSync(p).nlink!==1))throw new Error('check run must be an unlinked regular file');const content=String(a.content??'');if(content.length>600000)throw new Error('check script is too large');mkdirSync(resolve(p,'..'),{recursive:true});writeFileSync(p,content);return {ok:true};}return t.run(a);}})),after:(x:X)=>{pg.candidate(x.run.id);return 'ok';}});
