 engine.modes['pack-propose']={maxTools:30,sandbox:x=>({writes:[],cwd:pg.work(x.run.id)}),system:(_x,s)=>s,prompt:x=>{const g=pg.get(x.run.id);return `NATIVE PACK PROPOSE\nPack id: ${g.id}\nProposals: ${stable(g.proposals.filter(p=>p.status==='offered'))}`;},tools:x=>[tool('proposal_plan','Propose a parameter patch to a declared check, or a complete new advisory Studio JS check. The next native check measures this proposal before the captain decides.',a=>{guard(x);return pg.plan(x.run.id,String(a.proposal),a.plan);})],after:()=> 'ok'};
 engine.natives['pack-genesis-preview']=async(_i,h)=>{const proposals=await pg.preview(h.x as X),valid=proposals.every(p=>p.expected&&!p.expected.errors);return {verdict:valid?'pass':'warn',score:valid?1:0,findings:[],data:{route:'review',proposals}};};
 engine.cardModes['pack-proposals']={async start(x){const g=pg.get(x.run.id);await engine.card(x,'retro',body('Decide each measured check proposal','決定每個實測檢查提案',`${g.proposals.filter(p=>p.status==='offered').length} proposals need a decision. Accept or edit leads to refinement and remeasurement; rejection is retained.`,`${g.proposals.filter(p=>p.status==='offered').length} 個提案需要決定。接受或編輯會進入修正與重新實測；拒絕會保留。`,[{id:'continue',label:'Continue',primary:true},{id:'close',label:'Close',hold:true}],[{label:'Measured proposals',href:`#/pack-genesis/${x.run.id}`} ]));return {wait:true};},async answer(x,c){if(c.answer!.choice==='close')return {outcome:'close'};const g=pg.get(x.run.id);if(g.proposals.some(p=>p.status==='offered'))throw new Error('decide every offered proposal');return {outcome:g.proposals.some(p=>(p.status==='accepted'||p.status==='edited')&&!p.after)?'refine':'shadow'};}};
 engine.cardModes['pack-shadow']={async start(x){await engine.card(x,'acceptance',body('Run advisory shadow Tasks','執行建議用途的影子任務','Start actual work using this pinned candidate. Each Task needs a final captain acceptance or rejection. These checks do not block.','使用這個鎖定候選套件開始實際工作。每個任務都需要船長最後接受或拒絕。這些檢查不阻擋流程。',[{id:'continue',label:'Compare completed Tasks',primary:true},{id:'close',label:'Close',hold:true}],[{label:'Shadow Tasks',href:`#/pack-genesis/${x.run.id}`} ]));return {wait:true};},async answer(x,c){if(c.answer!.choice==='close')return {outcome:'close'};const g=pg.get(x.run.id);if(!g.shadow.some(s=>s.decision&&s.candidateHash===g.candidateHash))throw new Error('complete a real shadow Task and its captain decision first');return {outcome:hash(pg.evalSet(g))===g.evalHash?'promote':'measure'};}};
 engine.cardModes['pack-promote']={async start(x){const g=pg.get(x.run.id),rows=Object.keys(g.promotion).map(id=>pg.eligibility(g,id));await engine.card(x,'promote',body('Choose which measured checks may block','選擇哪些實測檢查可以阻擋流程',rows.map(r=>`${r.check}: ${r.matches}/${r.completed} matches; needs ${r.n}/${r.m}; ${r.eligible?'eligible':'advisory / needs your eye'}`).join('\n'),rows.map(r=>`${r.check}：${r.matches}/${r.completed} 次吻合；需要 ${r.n}/${r.m}；${r.eligible?'可升級':'保持建議用途／需要船長查看'}`).join('\n'),[{id:'continue',label:'Apply selected promotion',primary:true},{id:'more-shadow',label:'Run more shadow Tasks',hold:true},{id:'close',label:'Close',hold:true}],[{label:'Per-check policy and evidence',href:`#/pack-genesis/${x.run.id}`} ]));return {wait:true};},async answer(x,c){if(c.answer!.choice==='close')return {outcome:'close'};if(c.answer!.choice==='more-shadow')return {outcome:'more-shadow'};const g=pg.get(x.run.id);for(const [id,p]of Object.entries(g.promotion)){if(p.selected&&!pg.eligibility(g,id).eligible)throw new Error('a selected check no longer meets its threshold');p.blocking=p.selected&&pg.eligibility(g,id).eligible;}pg.save(g);return {outcome:'continue'};}};
 engine.cardBodies['pack-publish']=x=>{const g=pg.get(x.run.id);return body('Publish this immutable local pack version','發布這個不可變的本機套件版本',`Pin every file, the eval set and measured metrics. ${Object.values(g.promotion).filter(p=>!p.blocking).length} checks remain advisory. Nothing is sent to an external service.`,`鎖定每個檔案、評測集和實測指標。${Object.values(g.promotion).filter(p=>!p.blocking).length} 個檢查保持建議用途。不會傳送到外部服務。`,[{id:'publish',label:'Publish local version',primary:true},{id:'close',label:'Close',hold:true}],[{label:'Publication evidence',href:`#/pack-genesis/${x.run.id}`}]);};
 const packOf=(x:X)=>{const bound=(x.run.def as any).packPin;if(!bound?.namespace||!bound?.hash)throw new Error('producer requires its pinned native definition');if(x.run.params.packNamespace&&x.run.params.packNamespace!==bound.namespace||x.run.params.packHash&&x.run.params.packHash!==bound.hash)throw new Error('Task parameters cannot replace the definition hash pin');const pin=pg.pin(String(bound.namespace),String(bound.hash));if(x.run.params.genesis&&x.run.params.genesis!==pin.genesis)throw new Error('Task cannot replace its genesis provenance');return pin;};
 engine.modes['pack-produce']={maxTools:20,begin:x=>{packOf(x);mkdirSync(roundWorkPath(o.dataDir,'pack-results',x.run.id),{recursive:true});x.ctx.head=packOf(x).hash;x.save();},sandbox:x=>({writes:[roundWorkPath(o.dataDir,'pack-results',x.run.id)],cwd:roundWorkPath(o.dataDir,'pack-results',x.run.id)}),system:(_x,s)=>s,prompt:x=>`NATIVE PACK PRODUCE\nRequest: ${x.run.text}\nReturn an actual artifact version with result_create.`,tools:x=>[tool('result_create','Create the actual self-contained HTML or Markdown output of this Task.',a=>{guard(x);packOf(x);if(a.type!==undefined&&!['doc','web'].includes(a.type))throw new Error('this producer supports declared web or doc artifacts');const type=a.type==='doc'?'doc':'web',content=String(a.content??'');if(!content.trim()||content.length>500000||redactText(content)!==content)throw new Error('result is empty, too large or contains credentials');const id=`pack-result-${x.run.id.toLowerCase()}-${x.visit}`,dir=roundWorkPath(o.dataDir,'pack-results',x.run.id);mkdirSync(dir,{recursive:true});const primary=type==='doc'?'result.md':'index.html';writeFileSync(join(dir,primary),content);o.artifacts.create({id,title:String(a.title??x.run.title),type,source:type==='doc'?'md':'html',entry:primary,project:'native-pack'});const v=o.artifacts.addVersion(id,{from:dir,primary,createdBy:{kind:'agent',run:x.run.id},source:{run:x.run.id},status:'in-review'});x.ctx.packArtifact={artifact:id,version:v.n,sha256:v.sha256};x.save();return x.ctx.packArtifact;})],after:x=>{packOf(x);if(!x.ctx.packArtifact)throw new Error('producer did not write an actual artifact');return 'ok';}};
